float vrchVolumetricPyramidDistance(vec3 point) {
  float side = max(abs(point.x), abs(point.z)) - 0.52 * (0.88 - point.y);
  return max(max(side, point.y - 0.88), -0.72 - point.y);
}
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 point = (2.0 * fragCoord - iResolution.xy) / max(iResolution.y, 1.0);
  float angle = iTime * uParam_rotation_speed;
  float cosine = cos(angle);
  float sine = sin(angle);
  mat2 rotation = mat2(cosine, -sine, sine, cosine);
  mat2 inverseRotation = mat2(cosine, sine, -sine, cosine);
  vec3 rayOrigin = vec3(0.0, 0.0, 3.2);
  vec3 rayDirection = normalize(vec3(point, -1.8));
  float travelled = 0.0;
  float hit = 0.0;
  float nearDistance = 10.0;
  float scale = max(uParam_scale, 0.1);
  vec3 position = rayOrigin;
  for (int i = 0; i < 64; i++) {
    position = rayOrigin + rayDirection * travelled;
    vec3 objectPoint = position;
    objectPoint.xz = rotation * objectPoint.xz;
    objectPoint /= scale;
    float distanceToSurface = vrchVolumetricPyramidDistance(objectPoint) * scale;
    nearDistance = min(nearDistance, abs(distanceToSurface));
    if (distanceToSurface < 0.002) {
      hit = 1.0;
      break;
    }
    travelled += max(distanceToSurface * 0.65, 0.008);
    if (travelled > 6.0) break;
  }
  vec3 background = vec3(0.004, 0.006, 0.012) + 0.012 * vec3(0.08, 0.03, 0.01) / max(length(point), 0.35);
  vec3 color = background;
  if (hit > 0.5) {
    vec3 objectPoint = position;
    objectPoint.xz = rotation * objectPoint.xz;
    objectPoint /= scale;
    float axisX = abs(objectPoint.x);
    float axisZ = abs(objectPoint.z);
    vec3 normal;
    if (objectPoint.y < -0.70) {
      normal = vec3(0.0, -1.0, 0.0);
    } else if (axisX > axisZ) {
      normal = normalize(vec3(sign(objectPoint.x), 0.52, 0.0));
    } else {
      normal = normalize(vec3(0.0, 0.52, sign(objectPoint.z)));
    }
    normal.xz = inverseRotation * normal.xz;
    vec3 lightDirection = normalize(vec3(-0.45, 0.75, 0.65));
    float diffuse = max(dot(normal, lightDirection), 0.0);
    float fresnel = pow(1.0 - max(dot(normal, -rayDirection), 0.0), 3.0);
    vec3 glass = uParam_surface_color.rgb * (0.12 + 0.38 * diffuse);
    color = mix(background, glass + background * 0.3, clamp(uParam_opacity, 0.0, 1.0));
    color += vec3(1.0, 0.20, 0.035) * fresnel * uParam_glow;
  }
  float halo = exp(-18.0 * nearDistance) * (1.0 - hit) * uParam_glow;
  color += vec3(1.0, 0.16, 0.025) * halo;
  color = color / (color + vec3(1.0));
  fragColor = vec4(color, 1.0);
}
